// Extract all links from the page
const cheerio = require('cheerio');
const baseUrl = $input.first().json.baseUrl;
const html = $input.first().json.data;

const $ = cheerio.load(html);
const links = new Set();

$('a[href]').each((i, elem) => {
  let href = $(elem).attr('href');

  // Convert relative URLs to absolute
  if (href.startsWith('/')) {
    href = new URL(href, baseUrl).href;
  } else if (!href.startsWith('http')) {
    href = new URL(href, baseUrl).href;
  }

  // Only include links from the same domain
  if (href.startsWith(baseUrl)) {
    links.add(href);
  }
});

return Array.from(links).map(url => ({ json: { url, baseUrl } }));

// Extract content and structure from each page
const cheerio = require('cheerio');
const url = $input.first().json.url;
const html = $input.first().json.data;
const baseUrl = $input.first().json.baseUrl;

const $ = cheerio.load(html);

// Extract page structure
const title = $('title').text() || $('h1').first().text() || 'Untitled';
const metaDescription = $('meta[name="description"]').attr('content') || '';

// Get relative path for categorization
const urlObj = new URL(url);
const relativePath = urlObj.pathname;
const pathParts = relativePath.split('/').filter(p => p);

// Extract main content (try different selectors)
let content = '';
const contentSelectors = [
  'article',
  'main',
  '.content',
  '#content',
  '.post',
  '.article',
  'body'
];

for (const selector of contentSelectors) {
  const element = $(selector).first();
  if (element.length) {
    // Remove scripts, styles, and nav elements
    element.find('script, style, nav, header, footer, .nav, .menu').remove();
    content = element.text().trim();
    if (content.length > 100) break;
  }
}

// If still no content, get body text
if (!content || content.length < 100) {
  const body = $('body').clone();
  body.find('script, style, nav, header, footer, .nav, .menu').remove();
  content = body.text().trim();
}

// Clean up whitespace
content = content.replace(/\s+/g, ' ').trim();

return [{
  json: {
    url,
    relativePath,
    pathParts,
    category: pathParts[0] || 'root',
    subcategory: pathParts[1] || '',
    title,
    metaDescription,
    content,
    contentLength: content.length
  }
}];

// Translate content using a translation API or service
// This is a placeholder - you'll need to integrate with an actual translation service
// Options: OpenAI, DeepL, Google Translate, LibreTranslate

const item = $input.first().json;
const targetLanguage = 'fr';

// For now, we'll mark content for translation
// You can integrate with translation APIs in the next node

return [{
  json: {
    ...item,
    needsTranslation: true,
    targetLanguage,
    originalContent: item.content,
    originalTitle: item.title
  }
}];

