// Process translation results and prepare for saving
const item = $input.first().json;

// Extract translated content
let translatedTitle = item.originalTitle;
let translatedContent = item.originalContent;

// If OpenAI response
if (item.choices && item.choices[0]) {
  const response = item.choices[0].message.content;
  // Parse the response to extract title and content
  const titleMatch = response.match(/Titre:\s*(.+?)\n/);
  const contentMatch = response.match(/Contenu:\s*([\s\S]+)/);

  if (titleMatch) translatedTitle = titleMatch[1].trim();
  if (contentMatch) translatedContent = contentMatch[1].trim();
}

// If Google Translate response
if (item.data && item.data.translations) {
  translatedTitle = item.data.translations[0].translatedText;
  translatedContent = item.data.translations[1].translatedText;
}

return [{
  json: {
    url: item.url,
    relativePath: item.relativePath,
    pathParts: item.pathParts,
    category: item.category,
    subcategory: item.subcategory,
    originalTitle: item.originalTitle,
    translatedTitle,
    originalContent: item.originalContent,
    translatedContent,
    timestamp: new Date().toISOString()
  }
}];

// Generate summary report
const items = $input.all();

const summary = {
  totalPages: items.length,
  categories: {},
  timestamp: new Date().toISOString(),
  pages: items.map(item => ({
    url: item.json.url,
    category: item.json.category,
    title: item.json.translatedTitle
  }))
};

// Count by category
items.forEach(item => {
  const cat = item.json.category;
  summary.categories[cat] = (summary.categories[cat] || 0) + 1;
});

return [{ json: summary }];
